const insertPrepaidStatement = `-- name: InsertPrepaidStatement :one
INSERT INTO purser.billing_invoices (
    tenant_id, invoice_number, document_kind, status, currency, amount, due_date, paid_at,
    base_amount, metered_amount, gross_metered_amount, prepaid_credit_applied,
    usage_details, period_start, period_end,
    presentment_amount_cents, presentment_currency, presentment_units_per_eur,
    presentment_reference_date, finalized_at, created_at, updated_at
) VALUES (
    $1::text::uuid,
    'STM-' || LPAD(nextval('purser.billing_invoice_number_seq')::text, 10, '0'),
    'prepaid_statement', 'paid', 'EUR', 0,
    $2::timestamptz, $2::timestamptz,
    $3::text::numeric, $4::text::numeric,
    $5::text::numeric, 0,
    $6::jsonb, $7::timestamptz, $8::timestamptz,
    0, 'EUR', 1, $2::date, $2::timestamptz, NOW(), NOW()
)
ON CONFLICT (tenant_id, period_start) WHERE period_start IS NOT NULL
DO NOTHING
RETURNING id::text AS id, invoice_number
`

type InsertPrepaidStatementParams struct {
	TenantID           string          `db:"tenant_id" json:"tenant_id"`
	FinalizedAt        time.Time       `db:"finalized_at" json:"finalized_at"`
	BaseAmount         string          `db:"base_amount" json:"base_amount"`
	MeteredAmount      string          `db:"metered_amount" json:"metered_amount"`
	GrossMeteredAmount string          `db:"gross_metered_amount" json:"gross_metered_amount"`
	UsageDetails       json.RawMessage `db:"usage_details" json:"usage_details"`
	PeriodStart        time.Time       `db:"period_start" json:"period_start"`
	PeriodEnd          time.Time       `db:"period_end" json:"period_end"`
}

type InsertPrepaidStatementRow struct {
	ID            string `db:"id" json:"id"`
	InvoiceNumber string `db:"invoice_number" json:"invoice_number"`
}

// A statement is finalized when it is written: nothing is due, so it is paid.
// It is stated in EUR, the currency of the prepaid balance.
func (q *Queries) InsertPrepaidStatement(ctx context.Context, arg InsertPrepaidStatementParams) (InsertPrepaidStatementRow, error) {
	row := q.db.QueryRowContext(ctx, insertPrepaidStatement,
		arg.TenantID,
		arg.FinalizedAt,
		arg.BaseAmount,
		arg.MeteredAmount,
		arg.GrossMeteredAmount,
		arg.UsageDetails,
		arg.PeriodStart,
		arg.PeriodEnd,
	)
	var i InsertPrepaidStatementRow
	err := row.Scan(&i.ID, &i.InvoiceNumber)
	return i, err
}

