const listPrepaidDoubleCharges = `-- name: ListPrepaidDoubleCharges :many
SELECT invoice.id::text AS invoice_id,
       invoice.tenant_id::text AS tenant_id,
       invoice.invoice_number,
       invoice.status,
       invoice.period_start::timestamptz AS period_start,
       invoice.period_end::timestamptz AS period_end,
       invoice.amount::text AS amount,
       invoice.prepaid_credit_applied::text AS prepaid_credit_applied,
       COALESCE(invoice.presentment_currency, invoice.currency)::text AS presentment_currency,
       COALESCE(invoice.presentment_amount_cents, ROUND(invoice.amount * 100)::bigint)::bigint AS presentment_amount_cents,
       settled.amount_micro::bigint AS settled_micro,
       COALESCE(lines.usage_amount, 0)::text AS usage_amount
FROM purser.billing_invoices invoice
JOIN LATERAL (
    SELECT SUM(settlement.amount_micro) AS amount_micro
    FROM purser.prepaid_usage_settlements settlement
    WHERE settlement.tenant_id = invoice.tenant_id
      AND settlement.billing_period_start >= invoice.period_start
      AND settlement.billing_period_start < invoice.period_end
) settled ON settled.amount_micro IS NOT NULL
LEFT JOIN LATERAL (
    SELECT SUM(line.amount) AS usage_amount
    FROM purser.invoice_line_items line
    WHERE line.invoice_id = invoice.id
      AND line.line_key <> 'base_subscription'
      AND line.pricing_source <> 'cluster_monthly'
) lines ON TRUE
WHERE invoice.document_kind = 'invoice'
  AND invoice.period_start IS NOT NULL
  AND invoice.period_end IS NOT NULL
  AND invoice.base_fee_period_start IS NULL
  AND invoice.status NOT IN ('draft', 'manual_review', 'cancelled')
  AND invoice.usage_details->>'prepaid_settled_usage_excluded' IS NULL
  AND (NOT $1::boolean OR invoice.tenant_id = $2::text::uuid)
ORDER BY invoice.period_start, invoice.tenant_id, invoice.id
LIMIT $3::integer
`

type ListPrepaidDoubleChargesParams struct {
	FilterTenant bool   `db:"filter_tenant" json:"filter_tenant"`
	TenantID     string `db:"tenant_id" json:"tenant_id"`
	ResultLimit  int32  `db:"result_limit" json:"result_limit"`
}

type ListPrepaidDoubleChargesRow struct {
	InvoiceID              string    `db:"invoice_id" json:"invoice_id"`
	TenantID               string    `db:"tenant_id" json:"tenant_id"`
	InvoiceNumber          string    `db:"invoice_number" json:"invoice_number"`
	Status                 string    `db:"status" json:"status"`
	PeriodStart            time.Time `db:"period_start" json:"period_start"`
	PeriodEnd              time.Time `db:"period_end" json:"period_end"`
	Amount                 string    `db:"amount" json:"amount"`
	PrepaidCreditApplied   string    `db:"prepaid_credit_applied" json:"prepaid_credit_applied"`
	PresentmentCurrency    string    `db:"presentment_currency" json:"presentment_currency"`
	PresentmentAmountCents int64     `db:"presentment_amount_cents" json:"presentment_amount_cents"`
	SettledMicro           int64     `db:"settled_micro" json:"settled_micro"`
	UsageAmount            string    `db:"usage_amount" json:"usage_amount"`
}

// Finalized usage invoices whose period holds prepaid usage settlements: the
// tenant was prepaid during the period, and usage its prepaid balance had
// already paid was rated again on the invoice. Invoices that leave
// prepaid-settled usage out record prepaid_settled_usage_excluded and are not
// listed. usage_amount is the invoice's usage lines without base and monthly
// cluster fees.
func (q *Queries) ListPrepaidDoubleCharges(ctx context.Context, arg ListPrepaidDoubleChargesParams) ([]ListPrepaidDoubleChargesRow, error) {
	rows, err := q.db.QueryContext(ctx, listPrepaidDoubleCharges, arg.FilterTenant, arg.TenantID, arg.ResultLimit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListPrepaidDoubleChargesRow{}
	for rows.Next() {
		var i ListPrepaidDoubleChargesRow
		if err := rows.Scan(
			&i.InvoiceID,
			&i.TenantID,
			&i.InvoiceNumber,
			&i.Status,
			&i.PeriodStart,
			&i.PeriodEnd,
			&i.Amount,
			&i.PrepaidCreditApplied,
			&i.PresentmentCurrency,
			&i.PresentmentAmountCents,
			&i.SettledMicro,
			&i.UsageAmount,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const startBillingPhase = `-- name: StartBillingPhase :execrows
UPDATE purser.tenant_subscriptions
SET billing_period_start = $1::timestamp,
    billing_period_end = $2::timestamp,
    next_billing_date = $2::timestamp,
    updated_at = NOW()
WHERE tenant_id = $3::text::uuid
`

type StartBillingPhaseParams struct {
	PeriodStart time.Time `db:"period_start" json:"period_start"`
	PeriodEnd   time.Time `db:"period_end" json:"period_end"`
	TenantID    string    `db:"tenant_id" json:"tenant_id"`
}

// A switch between prepaid and postpaid closed the current phase at
// period_start: the next phase's period runs from there.
func (q *Queries) StartBillingPhase(ctx context.Context, arg StartBillingPhaseParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, startBillingPhase, arg.PeriodStart, arg.PeriodEnd, arg.TenantID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const sumPrepaidUsageSettlementsForStatement = `-- name: SumPrepaidUsageSettlementsForStatement :one
SELECT COALESCE(SUM(amount_micro), 0)::bigint AS amount_micro,
       COUNT(*)::bigint AS settlements
FROM purser.prepaid_usage_settlements
WHERE tenant_id = $1::text::uuid
  AND billing_period_start >= $2::timestamptz
  AND billing_period_start < $3::timestamptz
`

type SumPrepaidUsageSettlementsForStatementParams struct {
	TenantID    string    `db:"tenant_id" json:"tenant_id"`
	PeriodStart time.Time `db:"period_start" json:"period_start"`
	PeriodEnd   time.Time `db:"period_end" json:"period_end"`
}

type SumPrepaidUsageSettlementsForStatementRow struct {
	AmountMicro int64 `db:"amount_micro" json:"amount_micro"`
	Settlements int64 `db:"settlements" json:"settlements"`
}

// What prepaid usage settlements took from the balance for usage of billing
// periods starting inside [period_start, period_end).
func (q *Queries) SumPrepaidUsageSettlementsForStatement(ctx context.Context, arg SumPrepaidUsageSettlementsForStatementParams) (SumPrepaidUsageSettlementsForStatementRow, error) {
	row := q.db.QueryRowContext(ctx, sumPrepaidUsageSettlementsForStatement, arg.TenantID, arg.PeriodStart, arg.PeriodEnd)
	var i SumPrepaidUsageSettlementsForStatementRow
	err := row.Scan(&i.AmountMicro, &i.Settlements)
	return i, err
}
